def models_of(blob):
    o = json.loads(blob)
    out = []
    if "brands" in o:
        for b in o["brands"]:
            for m in b["models"]:
                out.append((b["brand"], m))
    else:
        for m in o["models"]:
            out.append((o["brand"], m))
    return out

def mat_val(m):
    return m.get("Type de mat (lead/kelly)") or m.get("Type de mat") or ""

def norm_fields(m):
    return {
        "Diametre forage": m.get("Diametre forage",""),
        "Profondeur max": m.get("Profondeur max",""),
        "Puissance moteur": m.get("Puissance moteur",""),
        "Poids operationnel": m.get("Poids operationnel",""),
        "Type de mat (lead/kelly)": mat_val(m),
        "Longueur du mat": m.get("Longueur du mat",""),
        "Longueur du kelly": m.get("Longueur du kelly",""),
        "Type": m.get("Type",""),
    }

WATSON_MODEL_MAP = {"2500 CM":"2500"}

d = json.load(open(PATH, encoding='utf-8'))
f = d['Foreuse']

# ---- UPDATES (modeles existants) ----
update_blobs = [WATSON, SOIL_CASA, LIEB_IMT, COMACCHIO, MONT_FUR_MOVAX]
upd_count = 0; field_upd = 0; not_found = []
for blob in update_blobs:
    for brand, m in models_of(blob):
        model = WATSON_MODEL_MAP.get(m["model"], m["model"]) if brand=="Watson" else m["model"]
        nf = norm_fields(m)
        found_any = False
        for yr in f.get(brand, {}):
            if yr.startswith('_'): continue
            if model in f[brand][yr]:
                found_any = True
                specs = f[brand][yr][model]
                for k in SPEC_KEYS:
                    new = (nf.get(k) or "").strip()
                    old = (specs.get(k) or "").strip()
                    if not new or new in BLANK:
                        continue
                    # ne pas regresser: remplacer si vide/N/D, ou si plus detaille
                    if old in BLANK or len(new) > len(old):
                        if specs.get(k) != new:
                            specs[k] = new; field_upd += 1
        if found_any: upd_count += 1
        else: not_found.append(f"{brand} > {model}")

# ---- ADDS (Mait nouvelle marque + Traxxon 3000/4500) ----
add_count = 0
for brand, m in models_of(MAIT_TRAXXON):
    nf = norm_fields(m)
    specs = {k: (nf.get(k) or "N/D") for k in SPEC_KEYS}
    for k in SPEC_KEYS:
        if not specs[k].strip(): specs[k] = "N/D"
    specs.update({"_note_tech_texte":"","_note_tech_auteur":"","_note_tech_date":"","_actif":"Oui"})
    if brand not in f: f[brand] = {}
    for yr in YEARS:
        f[brand].setdefault(yr, {})
        f[brand][yr][m["model"]] = dict(specs)
    add_count += 1

json.dump(d, open(PATH, 'w', encoding='utf-8'), ensure_ascii=False, separators=(',', ':'))
json.load(open(PATH, encoding='utf-8'))  # validate

print(f"Modeles existants mis a jour : {upd_count}")
print(f"Champs renseignes/ameliores : {field_upd}")
print(f"Modeles ajoutes (Mait + Traxxon 3000/4500) : {add_count}")
if not_found:
    print("NON TROUVES (a verifier) :", not_found)
print("Marques Foreuse :", [b for b in f if not b.startswith('_')])
